function assessLayers(names,plans){const results=names.map(n=>{const p=plans[n]||{};const establish=layerChoices[n].establish.find(x=>x[1]===p.establish);let posture='STRAINS',effect='The capability remains possible, but the design requires added work or operational compromise.';if(establish?.[0]==='solution'){posture='BREAKS';effect='The opening-day solution became a building dependency. Change requires reconstruction, room interruption or a workaround.'}else if(establish?.[0]==='foundation'){posture='BENDS';effect='Durable room conditions remain useful while the selected technical and workflow layer can be replaced.'}else if(establish?.[0]==='capacity'){posture='STRAINS';effect='Reserved capacity helps, but an additional durable room condition must be resolved before the change is straightforward.'}return{name:n,posture,effect,establish:p.establish,changeable:p.changeable}});const breaks=results.filter(x=>x.posture==='BREAKS').length;const bends=results.filter(x=>x.posture==='BENDS').length;const overall=breaks>=2?'BREAKS':breaks===1||bends<3?'STRAINS':'BENDS';return{overall,results,why:overall==='BENDS'?'Each capability combines a durable physical condition with an explicitly replaceable technical or workflow layer.':overall==='BREAKS'?'Multiple opening-day solutions were embedded as long-life building dependencies.':'The portfolio can adapt, but at least one capability requires added work, disruption or compromise.'}};
