function evaluateProtection(n,choice){const strategy=layerChoices[n];if(choice==='room')return{posture:'STRAINS',level:'INFRASTRUCTURE MODIFICATION',today:'Strengthens the long-life physical conditions that support the care model.',supported:`${strategy.establish[0][1]} is positioned to remain useful.`,potential:`${strategy.establish[1][1]} may need to be added or expanded if the future model requires more support.`,lesson:'Protecting room conditions can preserve care quality and usability, but it does not guarantee future infrastructure capacity.'};if(choice==='pathway')return{posture:'STRAINS',level:'LOCALIZED ROOM REFINEMENT',today:'Reserves access and capacity without selecting the future technical solution.',supported:`${strategy.establish[1][1]} is positioned to support later change.`,potential:`${strategy.establish[0][1]} may need localized refinement when the future model is known.`,lesson:'Protecting pathways can reduce invasive reconstruction, but it does not predetermine every future room condition.'};return{posture:'BREAKS',level:'MATERIAL ALTERATION',today:'Reduces near-term delivery risk by coordinating the approved technology, workflow, layout and commissioning plan.',supported:'The project opens with a coordinated, working implementation.',potential:`A substantially different future model may require changes to ${strategy.establish[0][1]} and ${strategy.establish[1][1]}.`,lesson:'Opening-day optimization can reduce near-term delivery risk while increasing the importance of an explicit transition strategy.'}}
function assessProtection(names,protections){const results=names.map(n=>{const choice=validProtections.has(protections[n])?protections[n]:'pathway';return{name:n,choice,label:protectionChoices[choice].label,strategy:layerChoices[n],...evaluateProtection(n,choice)}});const breaks=results.filter(x=>x.posture==='BREAKS').length,strains=results.length-breaks;let status='ADAPTABLE WITH TARGETED INTERVENTION';if(breaks===1)status='MOSTLY ADAPTABLE, WITH ONE MATERIAL DEPENDENCY';if(breaks>=2)status='MULTIPLE MATERIAL DEPENDENCIES';const overall=breaks>=2?'BREAKS':'STRAINS';const pattern=breaks===0?`${strains} capabilities remain adaptable through targeted changes. The location of future work differs based on what the project protected.`:breaks===1?`${strains} capabilities can adapt through targeted changes; ${results.find(x=>x.posture==='BREAKS').name} may require more substantial alteration because opening-day delivery received the strongest protection.`:`${breaks} capabilities may require material alteration because opening-day delivery received the strongest protection.`;return{overall,status,results,pattern}}
