function assess(items,layers){const locks=items.filter(([n,c])=>c==='COMMIT NOW'&&layers[n]==='CURRENT SOLUTION');const ds=items.map(([n,c])=>c==='COMMIT NOW'?(layers[n]==='DURABLE FOUNDATION'?'foundation':'lock'):dim[c]);const coverage=[...new Set(ds.filter(x=>x&&x!=='lock'))];const adaptive=coverage.filter(x=>['capacity','replaceability','optionality'].includes(x));const missing=['foundation','capacity','replaceability','optionality'].filter(x=>!coverage.includes(x));if(locks.length)return{posture:'BREAKS',missing,locks,why:`${locks.map(x=>x[0]).join(' and ')} embedded a current solution as a long-life building dependency.`};if(coverage.includes('foundation')&&adaptive.length>=2)return{posture:'BENDS',missing,locks:[],why:'The portfolio combines durable infrastructure with at least two adaptive protections.'};return{posture:'STRAINS',missing,locks:[],why:coverage.includes('foundation')?'The foundation is present, but adaptive protections are incomplete.':'Future flexibility is present, but the durable physical foundation is missing.'};}
